EXECUTE $c1253j$CREATE OR REPLACE FUNCTION mission_factory_owner.provider_authoring_assert_v1(p_user uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a mission_factory_owner.provider_authoring_admissions; g mission_factory_owner.provider_authoring_runtime; release_sha text;
begin
 IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c464_control WHERE singleton AND complete AND authoring_enabled) THEN RAISE EXCEPTION 'MF_PROVIDER_AUTHORING_CLOSED' USING ERRCODE='55000';END IF;
 release_sha:=mission_factory_owner.staff_release_sha_v1();
 select * into g from mission_factory_owner.provider_authoring_runtime where singleton for share;
 -- Public compile request wrappers authenticate the editor; private service consumers use its immutable Native request actor.
 if mission_public_owner.public_authoring_allowed_v1(true)
 and g.enabled and g.qualified and g.edge_qualified and g.release_sha256=release_sha
 and exists(select 1 from public.profiles where id=p_user and role in('admin','master')) then return release_sha;end if;
 select * into a from mission_factory_owner.provider_authoring_admissions where actor_user=p_user for share;
 if g.singleton is null or not g.enabled or not g.qualified or not g.edge_qualified
  or g.release_sha256 is distinct from release_sha or a.actor_user is null or not a.enabled
  or a.expires_at<=clock_timestamp() or a.release_sha256 is distinct from release_sha
  or not exists(select 1 from public.profiles where id=p_user and role in('admin','master'))
  or not exists(select 1 from public.locations where id=a.location_id and is_test and is_active)
  or public._combat_presente(p_user,a.location_id) is distinct from true
 then raise exception 'MF_PROVIDER_ADMISSION_UNAVAILABLE' using errcode='55000'; end if;
 return release_sha;
end $function$
